#include <stdio.h>
#include <time.h>
int main() {
    struct tm timeStruct;
    timeStruct.tm_year = 123;  // 2023 - 1900
    timeStruct.tm_mon = 0;    // January (0-11)
    timeStruct.tm_mday = 1;   // 1st day
    timeStruct.tm_hour = 0;
    timeStruct.tm_min = 0;
    timeStruct.tm_sec = 0;
    timeStruct.tm_isdst = -1; // Daylight saving time not set
    time_t result = mktime(&timeStruct);
    if (result != (time_t)-1) {
        printf("Converted time: %ld\n", result);
    } else {
        printf("Error in conversion\n");
    }
    return 0;
}
